import os
import re
from pathlib import Path

# Load all grids from session logs
def load_grids():
    session_dir = os.environ.get('RLM_SESSION_DIR')
    if not session_dir:
        return {}

    session_log = os.path.join(session_dir, '..', 'sessions.pkl')
    jsonl_path = os.path.join(session_dir, '..', 'sessions', os.path.basename(session_dir) + '.jsonl')

    try:
        with open(jsonl_path, 'r') as f:
            lines = f.read().strip().split('\n')
    except:
        print("Could not load sessions file")
        return {}

    G = {}

    # Find demo input/output pairs and test input
    for line in lines[:50]:  # Limit for quick loading
        if not line.strip():
            continue

        # Parse demo/key pattern
        m = re.search(r'(Demo pair \d+ (?:input|output)|Test input|Wrong attempts) \((\d+)x(\d+)\)', line)
        if m:
            key = m.group(1)
            h, w = int(m.group(2)), int(m.group(3))

        # Now extract the next h lines of the grid
        if key and (line.strip()[-3] in ['i', 'o', 'x']):
            # Get grid data following this pattern
            grid_lines = []
            for lp in lines:
                if lp.strip() and len(lp.split()) == w:
                    grid_lines.append([int(x) for x in lp.split()])
                    if len(grid_lines) >= h:
                        break

            if len(grid_lines) == h:
                grid = grid_lines
                if key not in G:
                    G[key] = grid

    return G

