import json

def load_from_env():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', '/tmp/sessions'))

    # Try to find the session's main JSONL file
    base_name = os.path.basename(d)
    jsonl_path = os.path.join(os.path.dirname(d), 'sessions', base_name + '.jsonl')

    grids = {}
    G = {}

    # Parse session.log or session.jsonl
    try:
        if os.path.exists(jsonl_path):
            with open(jsonl_path) as f:
                content = f.read()

            # Find Demo pair/i/o blocks
            pattern = re.compile(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):', re.MULTILINE)
            matches = list(pattern.finditer(content))

            for match in matches:
                k, h, w = match.groups()
                h, w = int(h), int(w)

                # Extract grid
                idx = match.end()
                if idx < len(content):
                    remaining = content[idx:].split('\n')
                    if len(remaining) >= h:
                        grid = []
                        for i, row in enumerate(remaining):
                            if i < h and row.split():
                                vals = row.split()
                                if len(vals) >= w:
                                    grid.append([int(x[:2]) for x in row])
                            else:
                                break
                        if 0 <= idx < len(remaining) and idx > 5:
                            # Try parse each row
                            grid = []
                            start_idx = idx if content[idx] != '\n' else idx + 1
                            grid_lines = []
                            for row in remaining[start_idx:start_idx+h]:
                                if row.strip():
                                    grid_lines.append([int(x) for x in row.split()])
                            if len(grid_lines) == h:
                                grid = grid_lines
                        if k not in G:
                            # Debug print what k is
                            print(f"Found key: {k[:10] if k else 'None'}...")
                            G[k] = grid
    except Exception as e:
        print(f"Error loading: {e}")
        import traceback
        traceback.print_exc()

    return G

