    for c in range(w):
        # Fill from neighbors
        changed = True
        while changed and pvals[c] == 0:
            changed = False
            # Try left
            for dc in range(-1, -c-1, -1):
                cc = c + dc
                if 0 <= cc < w and pvals[cc] != 0:
                    pvals[c] = pvals[cc]
                    changed = True
                    break
            # Try right
            for dc in range(1, w - c):
                cc = c + dc
                if 0 <= cc < w and pvals[cc] != 0:
                    pvals[c] = pvals[cc]
                    changed = True
                    break
            # Last resort: nearest non-zero in same row
            for dc in range(-w, w+1):
